BEGIN;
DO $test$
DECLARE t uuid:=gen_random_uuid();u uuid:=gen_random_uuid();site uuid:=gen_random_uuid();depot uuid:=gen_random_uuid();art uuid:=gen_random_uuid();cust uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();w uuid:=gen_random_uuid();qid uuid;sid uuid;li uuid;tok uuid;v text;r jsonb;items jsonb;req text:=gen_random_uuid()::text;ret uuid;other jsonb;reg uuid:=gen_random_uuid();cs uuid:=gen_random_uuid();pm uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();req2 text:=gen_random_uuid()::text;req3 text:=gen_random_uuid()::text;
BEGIN
 INSERT INTO public.tenants(id,name,enabled_modules,settings) VALUES(t,'RECETTE REPRISE DURABLE','[]','{"stock_method":"lot"}');
 INSERT INTO auth.users(id,email,aud,role) VALUES(u,u::text||'@example.invalid','authenticated','authenticated');
 INSERT INTO public.profiles(id,tenant_id,role,site_access_mode,full_name,is_active) VALUES(u,t,'admin','all','Commercial recette',true) ON CONFLICT(id) DO UPDATE SET tenant_id=excluded.tenant_id,role=excluded.role,site_access_mode=excluded.site_access_mode,is_active=true;
 INSERT INTO public.sites(id,tenant_id,name,is_active,allow_negative_stock) VALUES(site,t,'Magasin recette',true,false);
 INSERT INTO public.sites(id,tenant_id,name,is_active,is_warehouse,parent_site_id,allow_negative_stock) VALUES(depot,t,'Dépôt recette',true,true,site,false);
 INSERT INTO public.articles(id,tenant_id,internal_ref,name,sale_price,purchase_price,track_stock,vat_rate) VALUES(art,t,'REC-001','Article recette',1000,500,true,18);
 INSERT INTO public.customers(id,tenant_id,name) VALUES(cust,t,'Client recette');
 INSERT INTO public.stock_levels(tenant_id,article_id,site_id,quantity) VALUES(t,art,depot,10),(t,art,site,99);
 INSERT INTO public.stock_lots(id,tenant_id,article_id,site_id,batch_number,expiry_date,initial_quantity,remaining_quantity,purchase_price) VALUES(a,t,art,depot,'A001',current_date+30,6,6,400),(b,t,art,depot,'B002',current_date+60,4,4,600);
 INSERT INTO public.cash_registers(id,tenant_id,site_id,code,name) VALUES(reg,t,site,'C1','Caisse recette');
 INSERT INTO public.cash_sessions(id,tenant_id,site_id,user_id,cash_register_id,status,theoretical_amount) VALUES(cs,t,site,u,reg,'open',100);
 INSERT INTO public.payment_methods(id,tenant_id,name,code,payment_type,is_active) VALUES(pm,t,'Espèces','CASH','cash',true);
 INSERT INTO public.sales_vat_settings(tenant_id,site_id,enabled) VALUES(t,site,true);

 UPDATE public.sales_vat_settings SET enabled=false WHERE tenant_id=t;
 sid:=gen_random_uuid();li:=gen_random_uuid();
 INSERT INTO public.sales(id,tenant_id,site_id,cash_session_id,customer_id,user_id,sale_number,subtotal,total,paid,status,source,vat_enabled_at_issue) VALUES(sid,t,site,cs,cust,u,'HIST-001',10000,10000,1000,'partial','pos',false);
 INSERT INTO public.sale_items(id,tenant_id,sale_id,article_id,name,quantity,unit_price,total,purchase_cost,site_id) VALUES(li,t,sid,art,'Article recette',10,1000,10000,500,depot);
 INSERT INTO public.sale_lot_deductions(tenant_id,sale_id,sale_item_id,lot_id,article_id,site_id,quantity) VALUES(t,sid,li,a,art,depot,6),(t,sid,li,b,art,depot,4);
 UPDATE public.stock_levels SET quantity=0 WHERE tenant_id=t AND site_id=depot;
 UPDATE public.stock_lots SET remaining_quantity=0 WHERE tenant_id=t;
 INSERT INTO public.sale_payments(tenant_id,sale_id,payment_method_id,method_name,amount,status,cash_session_id) VALUES(t,sid,pm,'Espèces',1000,'confirmed',cs);
 UPDATE public.cash_sessions SET theoretical_amount=10100 WHERE id=cs;
 PERFORM set_config('request.jwt.claim.sub',u::text,true); EXECUTE 'SET LOCAL ROLE authenticated';
 items:=jsonb_build_array(jsonb_build_object('sale_item_id',li,'quantity',1,'lots',jsonb_build_array(jsonb_build_object('lot_id',a,'quantity',1))));
 r:=public.stage_return_request(req,'invoice',sid,site,NULL,items,'Retour différé',true,'deferred');
 IF r->>'state' IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'Préparation incorrecte';END IF;
 r:=public.read_active_return_request();
 IF r->>'request_key' IS DISTINCT FROM req THEN RAISE EXCEPTION 'Reprise introuvable';END IF;
 BEGIN PERFORM public.stage_return_request(req2,'invoice',sid,site,NULL,items,'Autre retour',true,'deferred');RAISE EXCEPTION 'Deux demandes actives';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 BEGIN PERFORM public.stage_return_request(req,'invoice',sid,site,NULL,items,'Retour modifié',true,'avoir');RAISE EXCEPTION 'Modification acceptée';EXCEPTION WHEN unique_violation THEN NULL;END;
 EXECUTE 'RESET ROLE';
 IF EXISTS(SELECT 1 FROM public.sale_returns WHERE tenant_id=t) OR (SELECT quantity FROM public.stock_levels WHERE tenant_id=t AND site_id=depot)<>0 THEN RAISE EXCEPTION 'Préparation avec effet métier';END IF;
 INSERT INTO auth.users(id,email,aud,role) VALUES(other_user,other_user::text||'@example.invalid','authenticated','authenticated');
 INSERT INTO public.profiles(id,tenant_id,role,site_access_mode,full_name,is_active) VALUES(other_user,t,'admin','all','Autre opérateur',true);
 PERFORM set_config('request.jwt.claim.sub',other_user::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 IF public.read_active_return_request() IS NOT NULL THEN RAISE EXCEPTION 'Lecture du journal étranger';END IF;
 BEGIN PERFORM public.execute_return_request(req);RAISE EXCEPTION 'Exécution étrangère';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',u::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.execute_return_request(req);ret:=(r->>'id')::uuid;
 IF ret IS NULL OR r->>'status' IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'Exécution invalide';END IF;
 r:=public.read_active_return_request();
 IF r->>'state' IS DISTINCT FROM 'succeeded' OR (r->'result'->>'id')::uuid IS DISTINCT FROM ret THEN RAISE EXCEPTION 'Résultat perdu après coupure';END IF;
 r:=public.execute_return_request(req);
 IF (r->>'id')::uuid IS DISTINCT FROM ret THEN RAISE EXCEPTION 'Réexécution différente';END IF;
 BEGIN PERFORM public.finish_return_request(req,'cancel');RAISE EXCEPTION 'Annulation après succès';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 r:=public.finish_return_request(req,'ack');
 IF r->>'state' IS DISTINCT FROM 'acknowledged' OR public.read_active_return_request() IS NOT NULL THEN RAISE EXCEPTION 'Accusé incorrect';END IF;
 r:=public.stage_return_request(req2,'invoice',sid,site,NULL,items,'Retour annulé',true,'deferred');
 r:=public.finish_return_request(req2,'cancel');
 IF r->>'state' IS DISTINCT FROM 'cancelled' THEN RAISE EXCEPTION 'Annulation incorrecte';END IF;
 BEGIN PERFORM public.execute_return_request(req2);RAISE EXCEPTION 'Exécution après annulation';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 r:=public.stage_return_request(req3,'invoice',sid,site,NULL,jsonb_build_array(jsonb_build_object('sale_item_id',li,'quantity',999)),'Retour invalide',true,'deferred');
 BEGIN PERFORM public.execute_return_request(req3);RAISE EXCEPTION 'Retour excessif accepté';EXCEPTION WHEN raise_exception THEN IF SQLERRM='Retour excessif accepté' THEN RAISE;END IF;END;
 IF public.read_active_return_request()->>'state' IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'Échec non atomique';END IF;
 r:=public.finish_return_request(req3,'cancel');
 EXECUTE 'RESET ROLE';
 IF (SELECT count(*) FROM public.sale_returns WHERE tenant_id=t)<>1 OR (SELECT quantity FROM public.stock_levels WHERE tenant_id=t AND site_id=depot)<>1 OR (SELECT theoretical_amount FROM public.cash_sessions WHERE id=cs)<>10100 THEN RAISE EXCEPTION 'Retour dupliqué ou soldes modifiés';END IF;
 IF public.br_check_schema_drift()->>'drift_detected' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'Registre sauvegarde incomplet';END IF;
 IF has_table_privilege('authenticated','public.return_request_journal','SELECT') OR has_function_privilege('anon','public.execute_return_request(text)','EXECUTE') THEN RAISE EXCEPTION 'Accès direct non protégé';END IF;
END $test$;
ROLLBACK;
SELECT 'REPRISE_DURABLE_OK' AS resultat;